CREATE TABLE users(id CHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, pass_hash VARCHAR(100) NOT NULL,
 role ENUM('admin','supervisor','participant') NOT NULL DEFAULT 'participant', hide_ranking TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memorization_groups(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), name VARCHAR(120) NOT NULL, supervisor_id CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX(supervisor_id), FOREIGN KEY(supervisor_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE group_members(group_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,user_id), INDEX(user_id),
 FOREIGN KEY(group_id) REFERENCES memorization_groups(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE memorization_plans(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), user_id CHAR(36) NOT NULL UNIQUE, verses_per_day SMALLINT UNSIGNED NOT NULL CHECK(verses_per_day>0),
 start_date DATE NOT NULL, set_by CHAR(36) NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(set_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE memorization_records(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), user_id CHAR(36) NOT NULL, surah TINYINT UNSIGNED NOT NULL, from_ayah SMALLINT UNSIGNED NOT NULL, to_ayah SMALLINT UNSIGNED NOT NULL,
 rec_date DATE NOT NULL DEFAULT (CURRENT_DATE), type ENUM('حفظ جديد','مراجعة','تثبيت') NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
 rating TINYINT NULL CHECK(rating BETWEEN 1 AND 5), notes VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(from_ayah>=1 AND to_ayah>=from_ayah), INDEX(user_id,rec_date), INDEX(status),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(surah) REFERENCES surahs(id));
CREATE TABLE recitation_submissions(id CHAR(36) PRIMARY KEY, record_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, size_bytes INT NOT NULL CHECK(size_bytes<=10485760), duration_sec INT NULL, mime VARCHAR(60) NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(record_id), FOREIGN KEY(record_id) REFERENCES memorization_records(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE recitation_evaluations(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), record_id CHAR(36) NOT NULL, submission_id CHAR(36) NULL, supervisor_id CHAR(36) NOT NULL,
 decision ENUM('approved','rejected') NOT NULL, rating TINYINT NULL CHECK(rating BETWEEN 1 AND 5), notes VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(record_id),
 FOREIGN KEY(record_id) REFERENCES memorization_records(id) ON DELETE CASCADE, FOREIGN KEY(submission_id) REFERENCES recitation_submissions(id) ON DELETE SET NULL, FOREIGN KEY(supervisor_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE revision_assignments(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), user_id CHAR(36) NOT NULL, surah TINYINT UNSIGNED NOT NULL, from_ayah SMALLINT UNSIGNED NOT NULL, to_ayah SMALLINT UNSIGNED NOT NULL,
 note VARCHAR(500) NULL, assigned_by CHAR(36) NULL, closed TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(to_ayah>=from_ayah), INDEX(user_id,closed),
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(surah) REFERENCES surahs(id), FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE notifications(id CHAR(36) PRIMARY KEY DEFAULT (UUID()), user_id CHAR(36) NOT NULL, title VARCHAR(200) NOT NULL, body VARCHAR(500) NULL, is_read TINYINT(1) NOT NULL DEFAULT 0,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,is_read), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
